#!/usr/bin/env bash
# Create or replace Secret keiko-tls in a namespace, for deploy/kubernetes.
# The authority is generated by the keiko image, so the host needs only a
# container runtime and kubectl. The certificate names keiko and keiko-db in
# every in-cluster form. Usage: bash scripts/kube-tls.sh <namespace>
# KEIKO_IMAGE overrides the image (default: this checkout's released version).
# Replacing the Secret replaces the authority: restart both pods afterwards.
set -euo pipefail

ns="${1:?usage: bash scripts/kube-tls.sh <namespace>}"
root="$(cd "$(dirname "$0")/.." && pwd)"
version="$(sed -n 's/^  "version": "\(.*\)",$/\1/p' "$root/package.json")"
image="${KEIKO_IMAGE:-ghcr.io/sannrox/keiko:v$version}"
names="DNS:localhost,IP:127.0.0.1"
for service in keiko keiko-db; do
  for suffix in "" ".$ns" ".$ns.svc" ".$ns.svc.cluster.local"; do
    names="$names,DNS:$service$suffix"
  done
done

dir="$(mktemp -d)"
trap 'rm -rf "$dir"' EXIT
docker run --rm -e KEIKO_TLS_NAMES="$names" --entrypoint sh "$image" \
  -c 'bash scripts/db-tls.sh && tar -C tls -c ca.crt server.crt server.key' | tar -x -C "$dir"
kubectl -n "$ns" create secret generic keiko-tls \
  --from-file=tls.crt="$dir/server.crt" \
  --from-file=tls.key="$dir/server.key" \
  --from-file=ca.crt="$dir/ca.crt" \
  --dry-run=client -o yaml | kubectl apply -f -
